237	    /**
238	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
239	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
240	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
241	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
242	     *
243	     * @param city     the owner's city
244	     * @param lastName the owner's last name
245	     * @return the assigned customer code
246	     */
247	    private String nextCustomerCode(String city, String lastName) {
248	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
249	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
250	        int sequence = countOwnersInCity(city) + 1;
251	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
252	    }
253	
254	    /**
255	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
256	     * owner's city already contains this many owners.
257	     */
258	    private static final int CITY_CAPACITY = 50;
259	
260	    /**
261	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
262	     *
263	     * @param city the city to count owners for
264	     * @return the number of existing owners in that city
265	     */
266	    private int countOwnersInCity(String city) {
267	        return (int) this.clinicService.findAllOwners().stream()
268	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
269	            .count();
270	    }
271	
272	    /**
273	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
274	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
275	     *
276	     * @param customerCode     the owner's assigned customer code
277	     * @param registrationDate the owner's registration date
278	     * @return the assigned membership number
279	     */
280	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
281	        String yy = String.format("%02d", registrationDate.getYear() % 100);
282	        return String.format("%s-M%s", customerCode, yy);
283	    }
284	
285	    /**
286	     * Counts the existing owners that already share the given first name and last name, comparing
287	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
288	     * the number of namesakes that existed prior to this create.
289	     *
290	     * @param firstName the new owner's first name
291	     * @param lastName  the new owner's last name
292	     * @return the number of existing owners with the same first and last name
293	     */
294	    private int countNamesakes(String firstName, String lastName) {
295	        int count = 0;
296	        for (Owner existing : this.clinicService.findAllOwners()) {
297	            if (firstName.equalsIgnoreCase(existing.getFirstName())
298	                && lastName.equalsIgnoreCase(existing.getLastName())) {
299	                count++;
300	            }
301	        }
302	        return count;
303	    }
304	
305	    /**
306	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
307	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
308	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
309	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
310	     * string is what gets stored and returned.
311	     *
312	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
313	     *
314	     * @param telephone the raw telephone value supplied by the client
315	     * @return the normalized E.164 telephone number
316	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
317	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
318	     *                                 digits after the {@code '+'})
319	     */
320	    private static String normalizeTelephone(String telephone) {
321	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
322	        String digits;
323	        if (cleaned.startsWith("+")) {
324	            digits = cleaned.substring(1);
325	        } else {
326	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
327	            digits = "61" + national;
328	        }
329	        if (!digits.matches("[0-9]{8,15}")) {
330	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
331	                "telephone could not be normalized to a valid E.164 number");
332	        }
333	        return "+" + digits;
334	    }
335	
336	    /**
337	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
338	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
339	     *
340	     * @param telephone the stored telephone value, possibly {@code null}
341	     * @return the E.164 form, or the raw value when it cannot be normalized
342	     */
343	    private static String toComparableTelephone(String telephone) {
344	        try {
345	            return normalizeTelephone(telephone);
346	        } catch (ResponseStatusException ex) {
347	            return telephone;
348	        }
349	    }
350	
351	    /**
352	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
353	     * containing at least one dot, none of the three sections containing whitespace or an
354	     * additional {@code @}.
355	     */
356	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
357	
358	    /**
359	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
360	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
361	     * value is then stored and returned lower-cased.
362	     *
363	     * @param email the raw email value supplied by the client, possibly {@code null}
364	     * @return the lower-cased email, or {@code null} when none was supplied
365	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
366	     *                                 is not a syntactically valid address
367	     */
368	    private static String normalizeEmail(String email) {
369	        if (email == null) {
370	            return null;
371	        }
372	        if (!EMAIL_PATTERN.matcher(email).matches()) {
373	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
374	                "email must be a syntactically valid address");
375	        }
376	        return email.toLowerCase(Locale.ROOT);
377	    }
378	
379	    /**
380	     * Common street-type abbreviations expanded to their full word during address normalization.
381	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
382	     */
383	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
384	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
385	
386	    /**
387	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
388	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
389	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
390	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
391	     * address comparison (household duplicate detection and the shared household id).
392	     *
393	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
394	     *
395	     * @param address the raw address supplied by the client, possibly {@code null}
396	     * @return the normalized address
397	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
398	     *                                 after normalization (required field)
399	     */
400	    private static String normalizeAddress(String address) {
401	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
402	        if (collapsed.isEmpty()) {
403	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
404	                "address must not be blank");
405	        }
406	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
407	        StringBuilder normalized = new StringBuilder();
408	        for (int i = 0; i < tokens.length; i++) {
409	            if (i > 0) {
410	                normalized.append(' ');
411	            }
412	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
413	        }
414	        return normalized.toString();
415	    }
416	
417	    /**
418	     * Determines whether the given normalized E.164 telephone is already used by any owner other
419	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
420	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
421	     * inputs representing the same number are treated as duplicates.
422	     *
423	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
424	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
425	     * @return {@code true} if another owner already uses the telephone
426	     */
427	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
428	        for (Owner existing : this.clinicService.findAllOwners()) {
429	            if (excludeId != null && excludeId.equals(existing.getId())) {
430	                continue;
431	            }
432	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
433	                return true;
434	            }
435	        }
436	        return false;
437	    }
438	
439	}
